        // ----------------------------------------------------
// MazeGenerator
// Procedurally generates the 3D grid layout using a recursive backtracker algorithm.
// It creates winding paths, guarantees a clear start and exit, and populates the map structure.
// ----------------------------------------------------
        class MazeGenerator {
            constructor(width, height, engine) {
                this.engine = engine;
                this.width = width;
                this.height = height;
                this.map = Array(height).fill().map(() => Array(width).fill(1));
            }
            
            generate() {
                const stack = [];
                const startX = 1;
                const startY = 1;
                this.map[startY][startX] = 0;
                stack.push([startX, startY]);
                
                while (stack.length > 0) {
                    const current = stack[stack.length - 1];
                    const cx = current[0];
                    const cy = current[1];
                    
                    const dirs = [[0,-2],[2,0],[0,2],[-2,0]];
                    dirs.sort(() => Math.random() - 0.5);
                    
                    let moved = false;
                    for (let d of dirs) {
                        const nx = cx + d[0];
                        const ny = cy + d[1];
                        
                        if (nx > 0 && nx < this.width - 1 && ny > 0 && ny < this.height - 1 && this.map[ny][nx] === 1) {
                            this.map[cy + d[1]/2][cx + d[0]/2] = 0;
                            this.map[ny][nx] = 0;
                            stack.push([nx, ny]);
                            moved = true;
                            break;
                        }
                    }
                    
                    if (!moved) {
                        stack.pop();
                    }
                }
                
                for (let i = 0; i < 20; i++) {
                    const rx = Math.floor(Math.random() * (this.width - 10)) + 1;
                    const ry = Math.floor(Math.random() * (this.height - 10)) + 1;
                    const template = ROOM_TEMPLATES[Math.floor(Math.random() * ROOM_TEMPLATES.length)];
                    
                    for (let y = 0; y < 8; y++) {
                        for (let x = 0; x < 8; x++) {
                            if (ry + y < this.height - 1 && rx + x < this.width - 1) {
                                if (template[y][x] === 0) {
                                    this.map[ry + y][rx + x] = 0;
                                }
                            }
                        }
                    }
                }
                
                this.map[1][1] = 0;
                this.map[1][2] = 0;
                this.map[2][1] = 0;
                
                let ex = this.width - 2;
                let ey = this.height - 2;
                this.map[ey][ex] = 5;
                this.map[ey][ex-1] = 0;
                this.map[ey-1][ex] = 0;
                
                return {
                    map: this.map,
                    start: { x: 1.5, y: 1.5 },
                    exit: { x: ex + 0.5, y: ey + 0.5 }
                };
            }
        }



        class Vector2 {
            constructor(x = 0, y = 0) {
                this.x = x;
                this.y = y;
            }

            add(v) {
                this.x += v.x;
                this.y += v.y;
                return this;
            }

            sub(v) {
                this.x -= v.x;
                this.y -= v.y;
                return this;
            }

            mult(n) {
                this.x *= n;
                this.y *= n;
                return this;
            }

            div(n) {
                this.x /= n;
                this.y /= n;
                return this;
            }

            mag() {
                return Math.sqrt(this.x * this.x + this.y * this.y);
            }

            magSq() {
                return this.x * this.x + this.y * this.y;
            }

            normalize() {
                const m = this.mag();
                if (m !== 0 && m !== 1) {
                    this.div(m);
                }
                return this;
            }

            dist(v) {
                const dx = this.x - v.x;
                const dy = this.y - v.y;
                return Math.sqrt(dx * dx + dy * dy);
            }

            copy() {
                return new Vector2(this.x, this.y);
            }

            set(x, y) {
                this.x = x;
                this.y = y;
                return this;
            }

            static sub(v1, v2) {
                return new Vector2(v1.x - v2.x, v1.y - v2.y);
            }
        }

        const MathUtils = {
            clamp: (val, min, max) => Math.max(min, Math.min(max, val))
        };

        const NoiseGen = (function() {
            const p = [
                151,160,137,91,90,15,131,13,201,95,96,53,194,233,7,225,140,36,103,30,69,142,8,99,37,240,21,10,23,
                190,6,148,247,120,234,75,0,26,197,62,94,252,219,203,117,35,11,32,57,177,33,88,237,149,56,87,174,
                20,125,136,171,168,68,175,74,165,71,134,139,48,27,166,77,146,158,231,83,111,229,122,60,211,133,
                230,220,105,92,41,55,46,245,40,244,102,143,54,65,25,63,161,1,216,80,73,209,76,132,187,208,89,
                18,169,200,196,135,130,116,188,159,86,164,100,109,198,173,186,3,64,52,217,226,250,124,123,5,202,
                38,147,118,126,255,82,85,212,207,206,59,227,47,16,58,17,182,189,28,42,223,183,170,213,119,248,152,
                2,44,154,163,70,221,153,101,155,167,43,172,9,129,22,39,253,19,98,108,110,79,113,224,232,178,185,
                112,104,218,246,97,228,251,34,242,193,238,210,144,12,191,179,162,241,81,51,145,235,249,14,239,107,
                49,192,214,31,181,199,106,157,184,84,204,176,115,121,50,45,127,4,150,254,138,236,205,93,222,114,
                67,29,24,72,243,141,128,195,78,66,215,61,156,180
            ];
            
            const perm = new Array(512);
            for(let i = 0; i < 512; i++) {
                perm[i] = p[i & 255];
            }
            
            const fade = t => t * t * t * (t * (t * 6 - 15) + 10);
            
            const lerp = (t, a, b) => a + t * (b - a);
            
            const grad = (hash, x, y, z) => {
                const h = hash & 15;
                const u = h < 8 ? x : y;
                const v = h < 4 ? y : h === 12 || h === 14 ? x : z;
                return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
            };
            
            return {
                get: function(x, y, z) {
                    let X = Math.floor(x) & 255;
                    let Y = Math.floor(y) & 255;
                    let Z = Math.floor(z) & 255;
                    
                    x -= Math.floor(x);
                    y -= Math.floor(y);
                    z -= Math.floor(z);
                    
                    let u = fade(x);
                    let v = fade(y);
                    let w = fade(z);
                    
                    let A = perm[X] + Y;
                    let AA = perm[A] + Z;
                    let AB = perm[A + 1] + Z;
                    let B = perm[X + 1] + Y;
                    let BA = perm[B] + Z;
                    let BB = perm[B + 1] + Z;
                    
                    return lerp(w,
                        lerp(v,
                            lerp(u, grad(perm[AA], x, y, z), grad(perm[BA], x - 1, y, z)),
                            lerp(u, grad(perm[AB], x, y - 1, z), grad(perm[BB], x - 1, y - 1, z))
                        ),
                        lerp(v,
                            lerp(u, grad(perm[AA + 1], x, y, z - 1), grad(perm[BA + 1], x - 1, y, z - 1)),
                            lerp(u, grad(perm[AB + 1], x, y - 1, z - 1), grad(perm[BB + 1], x - 1, y - 1, z - 1))
                        )
                    );
                }
            };
        })();

        const Settings = {
            musicVol: 0.5,
            sfxVol: 1.0,
            quality: 'HIGH',
            swarm: 'NORMAL',
            speed: 'ZEN',
            
            parseVol(valStr) {
                if (valStr === 'OFF') {
                    return 0;
                }
                return parseInt(valStr.replace('%', '')) / 100;
            }
        };

        const customMusicPlayer = new Audio();
        customMusicPlayer.loop = true;
        customMusicPlayer.volume = Settings.musicVol;

        document.getElementById('btn-upload-music').addEventListener('click', () => {
            document.getElementById('music-upload').click();
        });

        document.getElementById('music-upload').addEventListener('change', (e) => {
            const file = e.target.files[0];
            if (file) {
                const url = URL.createObjectURL(file);
                customMusicPlayer.src = url;
                customMusicPlayer.play().catch(err => console.log(err));
                
                let displayName = file.name;
                if (displayName.length > 15) {
                    displayName = displayName.substring(0, 12) + '...';
                }
                document.getElementById('btn-upload-music').innerText = displayName;
            }
        });

        
        document.getElementById('set-music').addEventListener('input', (e) => {
            Settings.musicVol = parseInt(e.target.value) / 100;
            customMusicPlayer.volume = Settings.musicVol;
        });
        document.getElementById('set-sfx').addEventListener('input', (e) => {
            Settings.sfxVol = parseInt(e.target.value) / 100;
            if (window.Synth) window.Synth.updateVolumes();
        });

        document.querySelectorAll('.stepper').forEach(stepper => {
            const options = stepper.getAttribute('data-options').split(',');
            let currentIndex = options.indexOf(stepper.querySelector('span').innerText);
            
            if (currentIndex === -1) {
                currentIndex = 0;
            }
            
            stepper.addEventListener('click', () => {
                currentIndex = (currentIndex + 1) % options.length;
                const newVal = options[currentIndex];
                stepper.querySelector('span').innerText = newVal;
                
                if (stepper.id === 'set-music') {
                    Settings.musicVol = Settings.parseVol(newVal);
                    customMusicPlayer.volume = Settings.musicVol;
                }
                
                if (stepper.id === 'set-sfx') {
                    Settings.sfxVol = Settings.parseVol(newVal);
                    if (Synth) {
                        Synth.updateVolumes();
                    }
                }
                
                if (stepper.id === 'set-quality') {
                    Settings.quality = newVal;
                }
                
                if (stepper.id === 'set-swarm') {
                    Settings.swarm = newVal;
                }
                
                if (stepper.id === 'set-speed') {
                    Settings.speed = newVal;
                }
            });
        });

        // ----------------------------------------------------
// AudioSynth
// The completely custom Web Audio API synthesizer. 
// Generates everything from the background ambient pads to the jump scare noises programmatically.
// ----------------------------------------------------
        class AudioSynth {
            constructor() {
                this.ctx = null;
                this.sfxGain = null;
                this.initialized = false;
                this.scale = [261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33, 659.25, 783.99, 880.00, 1046.50];
                this.horrorNodes = [];
            }

            init() {
                if (this.initialized) {
                    return;
                }
                
                const AudioContext = window.AudioContext || window.webkitAudioContext;
                if (!AudioContext) {
                    return;
                }
                
                this.ctx = new AudioContext();
                this.sfxGain = this.ctx.createGain();
                this.sfxGain.connect(this.ctx.destination);
                
                this.updateVolumes();
                this.initialized = true;
            }

            updateVolumes() {
                if (!this.ctx) {
                    return;
                }
                this.sfxGain.gain.setTargetAtTime(Settings.sfxVol * 0.4, this.ctx.currentTime, 0.1);
            }

            playCapture(comboMultiplier) {
                if (!this.initialized || Settings.sfxVol === 0) {
                    return;
                }
                
                const osc = this.ctx.createOscillator();
                const env = this.ctx.createGain();
                
                const baseNote = Math.min(this.scale.length - 1, 3 + Math.floor(comboMultiplier / 2));
                
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(this.scale[baseNote] || 880, this.ctx.currentTime);
                osc.frequency.exponentialRampToValueAtTime((this.scale[baseNote] || 880) * 1.5, this.ctx.currentTime + 0.1);
                
                env.gain.setValueAtTime(0, this.ctx.currentTime);
                env.gain.linearRampToValueAtTime(0.8, this.ctx.currentTime + 0.02);
                env.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.3);
                
                osc.connect(env);
                env.connect(this.sfxGain);
                
                osc.start(this.ctx.currentTime);
                osc.stop(this.ctx.currentTime + 0.4);
            }

            playComboUp() {
                if (!this.initialized || Settings.sfxVol === 0) {
                    return;
                }
                
                const osc = this.ctx.createOscillator();
                const env = this.ctx.createGain();
                
                osc.type = 'square';
                osc.frequency.setValueAtTime(440, this.ctx.currentTime);
                osc.frequency.setValueAtTime(554.37, this.ctx.currentTime + 0.1);
                osc.frequency.setValueAtTime(659.25, this.ctx.currentTime + 0.2);
                
                env.gain.setValueAtTime(0, this.ctx.currentTime);
                env.gain.linearRampToValueAtTime(0.3, this.ctx.currentTime + 0.05);
                env.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.5);
                
                osc.connect(env);
                env.connect(this.sfxGain);
                
                osc.start(this.ctx.currentTime);
                osc.stop(this.ctx.currentTime + 0.6);
            }

            startHorrorAudio() {
                if (!this.initialized || Settings.sfxVol === 0) {
                    return;
                }
                
                // Breath (White noise + bandpass)
                const bufferSize = this.ctx.sampleRate * 2;
                const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
                const data = buffer.getChannelData(0);
                
                for (let i = 0; i < bufferSize; i++) {
                    data[i] = Math.random() * 2 - 1;
                }
                
                const noise = this.ctx.createBufferSource();
                noise.buffer = buffer;
                noise.loop = true;
                
                const filter = this.ctx.createBiquadFilter();
                filter.type = 'bandpass';
                filter.frequency.value = 500;
                filter.Q.value = 1.0;
                
                const lfo = this.ctx.createOscillator();
                lfo.frequency.value = 0.2;
                
                const lfoGain = this.ctx.createGain();
                lfoGain.gain.value = 400;
                
                lfo.connect(lfoGain);
                lfoGain.connect(filter.frequency);
                
                const breathGain = this.ctx.createGain();
                breathGain.gain.value = 0.5;
                
                noise.connect(filter);
                filter.connect(breathGain);
                breathGain.connect(this.sfxGain);
                
                noise.start();
                lfo.start();
                
                
                const osc1 = this.ctx.createOscillator();
                const osc2 = this.ctx.createOscillator();
                osc1.type = 'sine';
                osc2.type = 'sawtooth';
                osc1.frequency.value = 40;
                osc2.frequency.value = 41.5;
                
                const droneFilter = this.ctx.createBiquadFilter();
                droneFilter.type = 'lowpass';
                droneFilter.frequency.value = 100;
                
                const droneGain = this.ctx.createGain();
                droneGain.gain.value = 1.5;
                
                osc1.connect(droneFilter);
                osc2.connect(droneFilter);
                droneFilter.connect(droneGain);
                droneGain.connect(this.sfxGain);
                
                osc1.start();
                osc2.start();
                
                this.horrorNodes.push(noise, lfo, osc1, osc2);
                
                this.heartbeatTimer = 0;
                this.heartbeatActive = false;
            }

            updateHorrorAudio(dt) {
                if (!this.initialized || Settings.sfxVol === 0) {
                    return;
                }
                
                this.heartbeatTimer -= dt;
                
                if (!this.heartbeatActive && Math.random() < 0.005) {
                    this.heartbeatActive = true;
                    this.heartbeatTimer = 5000 + Math.random() * 5000;
                    this.heartbeatInterval = 300;
                }
                
                if (this.heartbeatActive) {
                    if (this.heartbeatTimer <= 0) {
                        this.heartbeatActive = false;
                    }
                    
                    this.heartbeatInterval -= dt;
                    
                    if (this.heartbeatInterval <= 0) {
                        this.playHeartbeat();
                        this.heartbeatInterval = 350 + Math.random() * 100;
                    }
                }
            }

            playHeartbeat() {
                const osc = this.ctx.createOscillator();
                const env = this.ctx.createGain();
                
                osc.type = 'sine';
                osc.frequency.setValueAtTime(40, this.ctx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(10, this.ctx.currentTime + 0.3);
                
                env.gain.setValueAtTime(0, this.ctx.currentTime);
                env.gain.linearRampToValueAtTime(1.0, this.ctx.currentTime + 0.05);
                env.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.3);
                
                osc.connect(env);
                env.connect(this.sfxGain);
                
                osc.start(this.ctx.currentTime);
                osc.stop(this.ctx.currentTime + 0.4);
            }

            stopHorrorAudio() {
                this.horrorNodes.forEach(n => n.stop());
                this.horrorNodes = [];
                this.heartbeatActive = false;
            }
        }
        
        const Synth = new AudioSynth();

        // ----------------------------------------------------
// InputManager
// Handles all user input (mouse, touch, keyboard). 
// Normalizes coordinate spaces and tracks mouse locking/unlocking seamlessly.
// ----------------------------------------------------
        class InputManager {
            constructor() {
                this.pointerPos = new Vector2(-1000, -1000);
                this.isPointerDown = false;
                this.keys = {};
                this.listeners = [];
                this.ambientGlow = document.getElementById('ambientGlow');
                
                this.bindEvents();
            }

            bindEvents() {
                const down = (e) => this.handlePointerDown(e);
                const move = (e) => this.handlePointerMove(e);
                const up = (e) => {
                    this.isPointerDown = false;
                    this.emit('up', this.pointerPos);
                };
                
                window.addEventListener('pointerdown', down);
                window.addEventListener('pointermove', move);
                window.addEventListener('pointerup', up);
                
                window.addEventListener('touchstart', (e) => {
                    if (e.target.tagName !== 'BUTTON' && !e.target.classList.contains('stepper')) {
                        e.preventDefault();
                    }
                    down(e.touches[0]);
                }, { passive: false });
                
                window.addEventListener('touchmove', (e) => {
                    e.preventDefault();
                    move(e.touches[0]);
                }, { passive: false });
                
                window.addEventListener('touchend', up);
                
                window.addEventListener('keydown', (e) => {
                    this.keys[e.key.toLowerCase()] = true;
                    
                    if (e.code === 'Escape' || e.code === 'Space') {
                        this.emit('pauseToggle');
                    }
                    
                                        if (e.key.toLowerCase() === 'm') {
                        if (customMusicPlayer.paused) {
                            customMusicPlayer.play().catch(err=>{});
                            customMusicPlayer.muted = false;
                        } else {
                            customMusicPlayer.pause();
                        }
                        const inst = document.getElementById('instruction-hud');
                        if (inst) {
                            inst.innerText = customMusicPlayer.paused ? "Music Paused (M)" : "Music Playing (M)";
                            setTimeout(() => {
                                if (window.currentGameEngine) {
                                    inst.innerText = window.currentGameEngine.currentState === 'PLAYING_HORROR' 
                                        ? "Use WASD to move. Mouse to look. Find the green light." 
                                        : "Press and hold to track fireflies";
                                }
                            }, 2000);
                        }
                    }
                });
                
                window.addEventListener('keyup', (e) => {
                    this.keys[e.key.toLowerCase()] = false;
                });
                
                window.addEventListener('mousemove', (e) => {
                    if (document.pointerLockElement === document.getElementById('game-canvas')) {
                        this.emit('mouseLook', { x: e.movementX, y: e.movementY });
                    }
                });
            }

            handlePointerDown(e) {
                Synth.init();
                
                if (window.currentGameEngine && window.currentGameEngine.currentState !== 'PLAYING_HORROR') {
                    if (customMusicPlayer.src && customMusicPlayer.paused && Settings.musicVol > 0 && !customMusicPlayer.muted) {
                        customMusicPlayer.play().catch(() => {});
                    }
                }
                
                this.isPointerDown = true;
                this.updatePointerPos(e);
                this.emit('down', this.pointerPos);
                
                if (window.currentGameEngine && window.currentGameEngine.currentState === 'PLAYING_HORROR') {
                    const canvas = document.getElementById('game-canvas');
                    canvas.requestPointerLock = canvas.requestPointerLock || canvas.mozRequestPointerLock;
                    canvas.requestPointerLock();
                }
            }

            handlePointerMove(e) {
                this.updatePointerPos(e);
            }

            updatePointerPos(e) {
                if (!e) {
                    return;
                }
                
                this.pointerPos.set(e.clientX, e.clientY);
                
                if (this.ambientGlow) {
                    this.ambientGlow.style.left = `${e.clientX}px`;
                    this.ambientGlow.style.top = `${e.clientY}px`;
                }
            }

            off(event, callback) { this.listeners = this.listeners.filter(l => l.event !== event || l.callback !== callback); }
            on(event, callback) {
                this.listeners.push({ event, callback });
            }

            emit(event, data) {
                this.listeners.forEach(l => {
                    if (l.event === event) {
                        l.callback(data);
                    }
                });
            }
        }
        
        window.Input = new InputManager();
        const Input = window.Input;

        class Particle {
            constructor(x, y, r, g, b, multiplier) {
                this.pos = new Vector2(x, y);
                this.vel = new Vector2();
                
                const angle = Math.random() * Math.PI * 2;
                const speed = (Math.random() * 6 + 2) * (1 + (multiplier * 0.05));
                
                this.vel.x = Math.cos(angle) * speed;
                this.vel.y = Math.sin(angle) * speed;
                
                this.color = `${r}, ${g}, ${b}`;
                this.life = 1.0;
                this.decay = Math.random() * 0.04 + 0.01;
                this.size = Math.random() * 3 + 1;
            }

            update() {
                this.pos.add(this.vel);
                this.vel.mult(0.92);
                this.life -= this.decay;
            }

            draw(ctx) {
                if (this.life <= 0) {
                    return;
                }
                
                ctx.beginPath();
                ctx.arc(this.pos.x, this.pos.y, this.size, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(${this.color}, ${this.life})`;
                
                if (Settings.quality === 'HIGH') {
                    ctx.shadowBlur = 6;
                    ctx.shadowColor = `rgba(${this.color}, ${this.life})`;
                }
                
                ctx.fill();
                ctx.shadowBlur = 0;
            }
        }

        class FloatingText {
            constructor(x, y, text, colorStr, scale) {
                this.pos = new Vector2(x, y);
                this.text = text;
                this.color = colorStr;
                this.life = 1.0;
                this.vy = -1.2;
                this.scale = scale || 1;
            }

            update() {
                this.pos.y += this.vy;
                this.life -= 0.02;
            }

            draw(ctx) {
                if (this.life <= 0) {
                    return;
                }
                
                ctx.font = `bold ${22 * this.scale}px var(--font-main)`;
                ctx.fillStyle = `rgba(${this.color}, ${this.life})`;
                ctx.textAlign = 'center';
                
                if (Settings.quality === 'HIGH') {
                    ctx.shadowBlur = 8;
                    ctx.shadowColor = `rgba(${this.color}, ${this.life})`;
                }
                
                ctx.fillText(this.text, this.pos.x, this.pos.y);
                ctx.shadowBlur = 0;
            }
        }

        // ----------------------------------------------------
// Firefly
// Represents a single 2D firefly/boid in the main menu flow state.
// Handles its own steering, glowing, and collision logic with the player's cursor.
// ----------------------------------------------------
        class Firefly {
            constructor(engine, isInitialSpawn, forceRed = false) {
                this.engine = engine;
                this.id = Math.random() * 10000;
                this.pos = new Vector2();
                this.isRed = forceRed;
                
                this.reset(isInitialSpawn);
            }

            reset(isInitialSpawn = false) {
                this.seedOffset = Math.random() * 10000;
                this.phase = Math.random() * Math.PI * 2;
                
                if (isInitialSpawn) {
                    this.pos.x = Math.random() * this.engine.width;
                    this.pos.y = Math.random() * this.engine.height;
                } else {
                    if (Math.random() > 0.8) {
                        this.pos.x = (Math.random() > 0.5) ? -50 : this.engine.width + 50;
                        this.pos.y = Math.random() * this.engine.height;
                    } else {
                        this.pos.x = Math.random() * this.engine.width;
                        this.pos.y = this.engine.height + 50 + Math.random() * 100;
                    }
                }
                
                if (this.isRed) {
                    this.type = 'red';
                    this.r = 255;
                    this.g = 40;
                    this.b = 40;
                    this.size = 6.0;
                    this.speed = 0.5; // Starts slow
                    this.points = 0;
                    this.trackSpeedMultiplier = 5.0;
                    this.hitRadius = 9999;
                    this.redLife = 0;
                } else {
                    const roll = Math.random();
                    if (roll > 0.95) {
                        this.type = 'gold';
                        this.r = 249;
                        this.g = 226;
                        this.b = 175;
                        this.size = 3.5;
                        this.speed = 2.0;
                        this.points = 150;
                        this.trackSpeedMultiplier = 0.9;
                        this.hitRadius = 100; // Increased
                    } else if (roll > 0.70) {
                        this.type = 'purple';
                        this.r = 203;
                        this.g = 166;
                        this.b = 247;
                        this.size = 2.5;
                        this.speed = 1.4;
                        this.points = 50;
                        this.trackSpeedMultiplier = 1.1;
                        this.hitRadius = 110; // Increased
                    } else {
                        this.type = 'blue';
                        this.r = 137;
                        this.g = 180;
                        this.b = 250;
                        this.size = 1.8;
                        this.speed = 0.8;
                        this.points = 20;
                        this.trackSpeedMultiplier = 1.5;
                        this.hitRadius = 120; // Increased
                    }
                }
                
                this.trackProgress = 0;
                this.isBeingTracked = false;
                this.panicMultiplier = 1.0;
                this.isActive = true;
            }

            update(time, deltaTime) {
                if (!this.isActive) {
                    return;
                }

                if (this.isRed) {
                    this.redLife += deltaTime;
                    
                    if (this.redLife > 2000) {
                        this.speed = Math.min(25.0, this.speed + 0.6);
                        const target = Input.pointerPos.x > 0 ? Input.pointerPos : new Vector2(this.engine.width / 2, this.engine.height / 2);
                        const dir = Vector2.sub(target, this.pos).normalize();
                        this.pos.add(dir.mult(this.speed));
                        
                        if (this.pos.dist(Input.pointerPos) < 150) {
                            this.isBeingTracked = true;
                            this.trackProgress += 1000;
                        }
                    } else {
                        this.isBeingTracked = false;
                        this.pos.x += Math.sin(this.redLife * 0.005) * 0.5;
                        this.pos.y += Math.cos(this.redLife * 0.005) * 0.5;
                    }
                } else {
                    const hasRed = this.engine.fireflies.some(f => f.isRed && f.isActive);
                    
                    if (hasRed) {
                                                const target = Input.pointerPos.x > 0 ? Input.pointerPos : new Vector2(this.engine.width / 2, this.engine.height / 2);
                        const away = Vector2.sub(this.pos, target).normalize();
                        this.pos.add(away.mult(this.speed * 4));
                        this.phase += 0.2;
                    } else {
                        const timeScale = this.type === 'purple' ? 0.0012 : 0.0007;
                        const nx = NoiseGen.get(this.id, time * timeScale, this.seedOffset);
                        const ny = NoiseGen.get(this.id + 100, time * timeScale, this.seedOffset);
                        
                        let speedSettingMult = 1.0;
                        if (Settings.speed === 'FAST') {
                            speedSettingMult = 1.5;
                        }
                        if (Settings.speed === 'ZEN') {
                            speedSettingMult = 0.7;
                        }
                        
                        const currentSpeed = this.speed * this.engine.difficulty * this.panicMultiplier * speedSettingMult;
                        
                        this.pos.x += nx * 4 * currentSpeed;
                        this.pos.y += ny * 4 * currentSpeed;
                          this.pos.x += (this.engine.width / 2 - this.pos.x) * 0.002 * currentSpeed;
                          this.pos.y += (this.engine.height / 2 - this.pos.y) * 0.002 * currentSpeed;
                        this.phase += 0.05;
                    }
                    
                    const hasRedFlies = this.engine.fireflies.some(f => f.isRed && f.isActive);
                    if (!hasRedFlies) {
                        const edge = 50; 
                        if (this.pos.x < edge) this.pos.x += (edge - this.pos.x) * 0.05; 
                        if (this.pos.x > this.engine.width - edge) this.pos.x -= (this.pos.x - (this.engine.width - edge)) * 0.05; 
                        if (this.pos.y < edge) this.pos.y += (edge - this.pos.y) * 0.05; 
                        if (this.pos.y > this.engine.height - edge) this.pos.y -= (this.pos.y - (this.engine.height - edge)) * 0.05;
                    } else if (this.pos.y < -150 || this.pos.x < -150 || this.pos.x > this.engine.width + 150 || this.pos.y > this.engine.height + 250) {
                        this.reset(false);
                    }
                    
                    this.isBeingTracked = false;
                    
                    if (Input.isPointerDown && this.pos.dist(Input.pointerPos) < this.hitRadius) {
                        this.isBeingTracked = true;
                    }
                }

                if (this.isBeingTracked) {
                    this.trackProgress += (80 * this.trackSpeedMultiplier) * (deltaTime / 1000);
                    
                    if (!this.isRed) {
                        this.panicMultiplier = MathUtils.clamp(this.panicMultiplier + 0.02, 1.0, 2.5);
                    }
                    
                    if (this.trackProgress >= 100) {
                        this.capture();
                    }
                } else {
                    this.trackProgress -= 180 * (deltaTime / 1000);
                    this.trackProgress = MathUtils.clamp(this.trackProgress, 0, 100);
                    
                    if (!this.isRed) {
                        this.panicMultiplier = MathUtils.clamp(this.panicMultiplier - 0.05, 1.0, 2.5);
                    }
                }
            }

            capture() {
                this.isActive = false;
                this.engine.onFireflyCaptured(this);
                if (!this.isRed) {
                    this.reset(false);
                }
            }

            draw(ctx) {
                if (!this.isActive) {
                    return;
                }
                
                const alpha = (Math.sin(this.phase) + 1) / 2 * 0.6 + 0.4;
                
                ctx.beginPath();
                ctx.arc(this.pos.x, this.pos.y, this.size * 1.5, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(${this.r}, ${this.g}, ${this.b}, ${alpha})`;
                
                if (Settings.quality === 'HIGH' || this.isRed) {
                    ctx.shadowBlur = this.type === 'gold' ? 20 : (this.isRed ? 60 : 10);
                    ctx.shadowColor = `rgba(${this.r}, ${this.g}, ${this.b}, ${alpha})`;
                }
                
                ctx.fill();
                ctx.shadowBlur = 0;

                if (this.trackProgress > 0 && !this.isRed) {
                    const radius = this.hitRadius * 0.7;
                    
                    ctx.beginPath();
                    ctx.arc(this.pos.x, this.pos.y, radius, 0, Math.PI * 2);
                    ctx.strokeStyle = `rgba(${this.r}, ${this.g}, ${this.b}, 0.2)`;
                    ctx.lineWidth = 2;
                    ctx.stroke();
                    
                    const startAngle = -Math.PI / 2;
                    const endAngle = startAngle + (Math.PI * 2 * (this.trackProgress / 100));
                    
                    ctx.beginPath();
                    ctx.arc(this.pos.x, this.pos.y, radius, startAngle, endAngle);
                    ctx.strokeStyle = `rgba(${this.r}, ${this.g}, ${this.b}, 0.9)`;
                    ctx.lineWidth = 4;
                    ctx.lineCap = 'round';
                    
                    if (Settings.quality === 'HIGH') {
                        ctx.shadowBlur = 8;
                        ctx.shadowColor = `rgba(${this.r}, ${this.g}, ${this.b}, 1)`;
                    }
                    
                    ctx.stroke();
                    ctx.shadowBlur = 0;
                }
            }
        }

        
// ----------------------------------------------------
// BackroomsEngine
// The entire 3D horror sequence is handled here.
// Sets up Three.js, manages the Weeping Angel monster, and handles raycast collisions for the maze.
// ----------------------------------------------------
        class BackroomsEngine {
    constructor(width, height, game) {
        this.width = width;
        this.height = height;
        this.game = game;
        this.canvas = game.canvas;
        this.ctx = game.ctx;
        
        this.mapWidth = 35;
        this.mapHeight = 35;
        const generator = new MazeGenerator(this.mapWidth, this.mapHeight);
        const genResult = generator.generate();
        this.map = genResult.map || genResult; this.exitPos = genResult.exit || {x: this.mapWidth - 1.5, y: this.mapHeight - 1.5};

        // Ensure player starts in empty space
        this.map[1][1] = 0;

        this.scene = new THREE.Scene();
        this.scene.background = new THREE.Color(0x020202);
        this.scene.fog = new THREE.FogExp2(0x020202, 0.25);

        this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 100);
          this.scene.add(this.camera);
        
        // Hide 2D canvas, overlay a new 3D canvas
        this.canvas.style.display = 'none';
        this.webglCanvas = document.createElement('canvas');
        this.webglCanvas.id = 'webgl-canvas';
        this.webglCanvas.style.position = 'absolute';
        this.webglCanvas.style.top = '0';
        this.webglCanvas.style.left = '0';
        this.webglCanvas.style.zIndex = '50';
        document.getElementById('app').appendChild(this.webglCanvas);
          this.webglCanvas.addEventListener('click', () => { document.body.requestPointerLock(); });
        
        this.renderer = new THREE.WebGLRenderer({ canvas: this.webglCanvas });
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        
        
        this.pitch = 0;
        this.camera.rotation.order = 'YXZ';
        
        // Face down the hallway instead of staring at a wall!
        this.camera.rotation.y = Math.PI; 
        
        this.mouseLookHandler = (movement) => {
            const movX = movement.x;
            const movY = movement.y;
            this.camera.rotation.y -= movX * 0.002;
            this.pitch -= movY * 0.002;
            this.pitch = Math.max(-Math.PI/2, Math.min(Math.PI/2, this.pitch));
            this.camera.rotation.x = this.pitch;
        };
        Input.on('mouseLook', this.mouseLookHandler);

        
        this.moveForward = false;
        this.moveBackward = false;
        this.moveLeft = false;
        this.moveRight = false;
        this.velocity = new THREE.Vector3();
        this.direction = new THREE.Vector3();

        this.setupLighting();
        this.buildMaze();
        
        this.monster = new THREE.Group();
        this.scene.add(this.monster);
        this.loadMonsterModel();

        this.camera.position.set(1.5, 0.5, 1.5);
        this.monsterState = 'stalking';
        this.frustum = new THREE.Frustum();
        this.projScreenMatrix = new THREE.Matrix4();
        this.heartbeatTimer = 0;

        // Flashlight state must start defined, or "undefined <= 0" silently
        // evaluates to false forever and the F key never does anything.
        this.flashlightBattery = 12.0;
        this.flashlightCooldown = 0;

        this.kd = (e) => this.onKeyDown(e);
        this.ku = (e) => this.onKeyUp(e);
        document.addEventListener('keydown', this.kd);
        document.addEventListener('keyup', this.ku);

        this.prevTime = performance.now();
        
        const combo = document.getElementById('combo-container');
        if(combo) combo.style.display = 'none';
        
        this.hasWon = false;
    }

    loadMonsterModel() {
        const loader = new THREE.GLTFLoader();
        const dracoLoader = new THREE.DRACOLoader();
        dracoLoader.setDecoderPath('https://www.gstatic.com/draco/versioned/decoders/1.4.1/');
        loader.setDRACOLoader(dracoLoader);
        loader.load('Hi3D_Untitled_allparts_20260827_090613.glb', (gltf) => {
            const model = gltf.scene;
            const box = new THREE.Box3().setFromObject(model);
            const center = box.getCenter(new THREE.Vector3());
            const size = box.getSize(new THREE.Vector3());
            const maxDim = Math.max(size.x, size.y, size.z);
            const scale = 2.0 / maxDim; 
            
            model.scale.set(scale, scale, scale);
            model.position.set(-center.x * scale, (-center.y * scale) + (size.y * scale)/2, -center.z * scale);
            
            
              model.traverse((child) => {
                  if (child.isMesh) {
                      child.material.color = new THREE.Color(0x1a1a1a); // Lighter black
                      if (child.material) {
                          child.material.roughness = 0.5; 
                          child.material.metalness = 0.2;
                      } // Dark Gray
                      // A heuristic for the face - assuming standard model structure or just making the whole head lighter
                      if (child.name.toLowerCase().includes('face') || child.name.toLowerCase().includes('head') || child.geometry.attributes.position.count < 1000) {
                          child.material.color = new THREE.Color(0xbbbbbb); // Light Gray Face
                      }
                  }
              });
              this.monsterMesh = model;

            this.monster.add(model);
            this.monster.position.set(this.mapWidth - 2.5, 0, this.mapHeight - 2.5);
        });
    }

    setupLighting() {
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.1);
        this.scene.add(ambientLight);
        
          this.flashlight = new THREE.SpotLight(0xfff0dd, 4.0, 60, Math.PI / 6, 0.6, 1);
          this.flashlight.position.set(0, 0, 0);
          this.flashlight.target.position.set(0, 0, -1);
          this.camera.add(this.flashlight.target);

        this.camera.add(this.flashlight);
        this.scene.add(this.camera);
    }

    buildMaze() {
        const wallGeo = new THREE.BoxGeometry(1, 2, 1);
        this.wallMat = new THREE.MeshPhongMaterial({ color: 0x888888, shininess: 10 });
        this.walls = [];
        const exitMat = new THREE.MeshBasicMaterial({ color: 0x00ff00 }); // Green exit
        
        for (let y = 0; y < this.mapHeight; y++) {
            for (let x = 0; x < this.mapWidth; x++) {
                if (this.map[y][x] === 1) {
                    const wall = new THREE.Mesh(wallGeo, this.wallMat);
                    wall.position.set(x + 0.5, 1, y + 0.5);
                    this.scene.add(wall);
                    this.walls.push(wall);
                } else if (this.map[y][x] === 5) {
                    const exit = new THREE.Mesh(wallGeo, exitMat);
                    exit.position.set(x + 0.5, 1, y + 0.5);
                    this.scene.add(exit);
                }
            }
        }

        const floorGeo = new THREE.PlaneGeometry(this.mapWidth, this.mapHeight);
        const floorMat = new THREE.MeshPhongMaterial({ color: 0x444444, shininess: 5 });
        const floor = new THREE.Mesh(floorGeo, floorMat);
        floor.rotation.x = -Math.PI / 2;
        floor.position.set(this.mapWidth / 2, 0, this.mapHeight / 2);
        this.scene.add(floor);
    }

    onKeyDown(event) {
        switch (event.code) {
            case 'ArrowUp': case 'KeyW': this.moveForward = true; break;
            case 'KeyF': if(this.flashlight && this.flashlightCooldown <= 0) this.flashlight.visible = !this.flashlight.visible; break;
            case 'ArrowLeft': case 'KeyA': this.moveLeft = true; break;
            case 'ArrowDown': case 'KeyS': this.moveBackward = true; break;
            case 'ArrowRight': case 'KeyD': this.moveRight = true; break;
            case 'ShiftLeft': case 'ShiftRight': this.moveShift = true; break;
        }
    }

    onKeyUp(event) {
        switch (event.code) {
            case 'ArrowUp': case 'KeyW': this.moveForward = false; break;
            case 'ArrowLeft': case 'KeyA': this.moveLeft = false; break;
            case 'ArrowDown': case 'KeyS': this.moveBackward = false; break;
            case 'ArrowRight': case 'KeyD': this.moveRight = false; break;
            case 'ShiftLeft': case 'ShiftRight': this.moveShift = false; break;
        }
    }

        // Mathematical collision check against the 2D array grid map.
    // Returns 1 for walls, 0 for empty space, and 5 for the exit door.
        getNextStep(sx, sz, tx, tz) {
        const start = {x: Math.floor(sx), z: Math.floor(sz)};
        const target = {x: Math.floor(tx), z: Math.floor(tz)};
        if (start.x === target.x && start.z === target.z) return null;
        
        const queue = [start];
        const visited = new Set();
        visited.add(`${start.x},${start.z}`);
        const parent = {};
        
        let found = false;
        while(queue.length > 0) {
            const curr = queue.shift();
            if (curr.x === target.x && curr.z === target.z) {
                found = true; break;
            }
            const neighbors = [
                {x: curr.x+1, z: curr.z}, {x: curr.x-1, z: curr.z},
                {x: curr.x, z: curr.z+1}, {x: curr.x, z: curr.z-1}
            ];
            for (let n of neighbors) {
                if (n.z >= 0 && n.z < this.mapHeight && n.x >= 0 && n.x < this.mapWidth) {
                    if (this.map[n.z][n.x] !== 1 && !visited.has(`${n.x},${n.z}`)) {
                        visited.add(`${n.x},${n.z}`);
                        parent[`${n.x},${n.z}`] = curr;
                        queue.push(n);
                    }
                }
            }
        }
        
        if (found) {
            let curr = target;
            while(parent[`${curr.x},${curr.z}`] && (parent[`${curr.x},${curr.z}`].x !== start.x || parent[`${curr.x},${curr.z}`].z !== start.z)) {
                curr = parent[`${curr.x},${curr.z}`];
            }
            return curr;
        }
        return null;
    }

    checkCollision(x, z) {
        const cx = Math.floor(x);
        const cz = Math.floor(z);
        if (cx < 0 || cx >= this.mapWidth || cz < 0 || cz >= this.mapHeight) return 1;
        return this.map[cz][cx];
    }

    triggerJumpscare() {
        this.monsterState = 'hidden';
        this.monster.position.y = -100;
        
        const flash = document.getElementById('glitch-flash');
        if (flash) {
            flash.style.background = "white";
            flash.style.display = 'block'; flash.style.opacity = 1;
            setTimeout(() => { flash.style.opacity = 0; }, 800);
        }

        try {
            const ctx = Synth.ctx; if(ctx) {
            const osc = ctx.createOscillator();
            const env = ctx.createGain();
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(80, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(10, ctx.currentTime + 0.8);
            env.gain.setValueAtTime(0, ctx.currentTime);
            env.gain.linearRampToValueAtTime(3.0, ctx.currentTime + 0.05);
            env.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.8);
            osc.connect(env);
            env.connect(ctx.destination);
            osc.start(ctx.currentTime);
            osc.stop(ctx.currentTime + 0.9);
        } } catch(e) {}

        setTimeout(() => {
            this.monsterState = 'stalking';
            this.monster.position.set(
                Math.floor(Math.random() * (this.mapWidth-2)) + 1.5,
                0,
                Math.floor(Math.random() * (this.mapHeight-2)) + 1.5
            );
        }, 10000);
    }

    
        // The main 3D rendering and logic loop. Called 60 times a second.
    // Handles physics, monster AI, flashlight, and radar UI updates.
update(dt) {
        if (this.hasWon) return true;
        const time = performance.now();
        const delta = Math.min((time - this.prevTime) / 1000, 0.1);

        // Stamina logic
        if (this.stamina === undefined) this.stamina = 100;
        if (this.exhausted === undefined) this.exhausted = false;
        
        if (this.stamina <= 0) this.exhausted = true;
        if (this.stamina > 30) this.exhausted = false;

        const isMoving = this.moveForward || this.moveBackward || this.moveLeft || this.moveRight;
        const isSprinting = this.moveShift && !this.exhausted && isMoving;

        if (isSprinting) {
            this.stamina = Math.max(0, this.stamina - 30 * delta);
        } else {
            this.stamina = Math.min(100, this.stamina + 2.5 * delta);
        }
        
        const staminaBar = document.getElementById('stamina-fill');
        if (staminaBar) {
            staminaBar.style.width = this.stamina + '%';
            staminaBar.style.backgroundColor = this.exhausted ? 'red' : '#00ff00';
        }

        let speed = isSprinting ? 3.5 : 2.0;

        // Player movement
        const dir = new THREE.Vector3();
        if (this.moveForward) dir.z -= 1;
        if (this.moveBackward) dir.z += 1;
        if (this.moveLeft) dir.x -= 1;
        if (this.moveRight) dir.x += 1;

        if (dir.lengthSq() > 0) {
            dir.normalize();
            dir.applyQuaternion(this.camera.quaternion);
            dir.y = 0;
            dir.normalize();

            // AABB Collision (X and Z checked independently to allow sliding)
            const pad = 0.2;
            let finalDeltaX = dir.x * speed * delta;
            let finalDeltaZ = dir.z * speed * delta;

            const nextXForX = this.camera.position.x + finalDeltaX;
            if (finalDeltaX !== 0) {
                const checkX = finalDeltaX > 0 ? this.camera.position.x + finalDeltaX + pad : this.camera.position.x + finalDeltaX - pad;
                const hit1 = this.checkCollision(checkX, this.camera.position.z - pad);
                const hit2 = this.checkCollision(checkX, this.camera.position.z + pad);
                
                if (hit1 === 1 || hit2 === 1) {
                    finalDeltaX = 0;
                } else if (hit1 === 5 || hit2 === 5) {
                    this.hasWon = true; return true;
                }
            }
            
            const nextXForZ = this.camera.position.x + finalDeltaX;
            if (finalDeltaZ !== 0) {
                const checkZ = finalDeltaZ > 0 ? this.camera.position.z + finalDeltaZ + pad : this.camera.position.z + finalDeltaZ - pad;
                const hit1 = this.checkCollision(nextXForZ - pad, checkZ);
                const hit2 = this.checkCollision(nextXForZ + pad, checkZ);
                
                if (hit1 === 1 || hit2 === 1) {
                    finalDeltaZ = 0;
                } else if (hit1 === 5 || hit2 === 5) {
                    this.hasWon = true; return true;
                }
            }
            
            this.camera.position.x += finalDeltaX;
            this.camera.position.z += finalDeltaZ;
        }

        // --- Battery UI Update ---
        const batteryBar = document.getElementById('flashlight-battery');
        if (this.flashlight && this.flashlight.visible) {
            this.flashlightBattery -= delta / 4;
            if (this.flashlightBattery <= 0) {
                this.flashlightBattery = 0;
                this.flashlight.visible = false;
                this.flashlightCooldown = 3.0;
            }
        } else {
            if (this.flashlightCooldown > 0) {
                this.flashlightCooldown -= delta;
                if (this.flashlightCooldown <= 0) this.flashlightCooldown = 0;
            } else if (this.flashlightBattery < 10.0) {
                this.flashlightBattery += delta / 8;
                if (this.flashlightBattery > 10.0) this.flashlightBattery = 10.0;
            }
        }
        if (batteryBar) {
            batteryBar.style.width = (this.flashlightBattery / 10.0 * 100) + '%';
            batteryBar.style.backgroundColor = (this.flashlightCooldown > 0) ? 'red' : 'rgb(250, 204, 21)';
        }

        // --- Death Sequence Logic ---
        if (this.isDead) {
            if (!this.neckSnapped) {
                this.neckSnapped = true;
                this.camera.rotation.set(this.pitch - 1.2, this.camera.rotation.y, 0.8, 'YXZ');
                this.pitch = this.camera.rotation.x;
            } else {
                this.camera.rotation.set(this.pitch, this.camera.rotation.y, 0.8, 'YXZ');
            }
            
            this.deathTimer -= delta;
            if (this.deathTimer <= 0) {
                return 'LOSE';
            }
            
            this.prevTime = time;
            return false;
        }

        // --- Monster Stalking Logic ---
        if (this.monsterState === 'stalking' || this.monsterState === 'attacking') {
            const mx = this.monster.position.x;
            const mz = this.monster.position.z;
            const px = this.camera.position.x;
            const pz = this.camera.position.z;
            const dist = Math.hypot(px - mx, pz - mz);
            
            const rDir = new THREE.Vector3(0, 0, -1).applyQuaternion(this.camera.quaternion); rDir.y = 0; rDir.normalize();
            const rRight = new THREE.Vector3(1, 0, 0).applyQuaternion(this.camera.quaternion); rRight.y = 0; rRight.normalize();
            
            const radarM = document.getElementById('radar-monster');
            if (radarM) {
                const vecX = mx - px; const vecZ = mz - pz;
                const fwd = vecX * rDir.x + vecZ * rDir.z;
                const rgt = vecX * rRight.x + vecZ * rRight.z;
                const rDx = rgt * 3; const rDz = -fwd * 3;
                const mDist = Math.hypot(rDx, rDz);
                let finalDx = rDx; let finalDz = rDz;
                if (mDist > 75) { finalDx = (rDx / mDist) * 75; finalDz = (rDz / mDist) * 75; }
                radarM.style.transform = 'translate(-50%, -50%)';
                radarM.style.left = `calc(50% + ${finalDx}px)`;
                radarM.style.top = `calc(50% + ${finalDz}px)`;
                radarM.style.display = 'block';
            }
            
            const radarExit = document.getElementById('radar-exit');
            if (radarExit && this.exitPos) {
                const vecX = this.exitPos.x - px; const vecZ = this.exitPos.y - pz;
                const fwd = vecX * rDir.x + vecZ * rDir.z;
                const rgt = vecX * rRight.x + vecZ * rRight.z;
                const eDx = rgt * 3; const eDz = -fwd * 3;
                const eDist = Math.hypot(eDx, eDz);
                let finalDx = eDx; let finalDz = eDz;
                if (eDist > 75) { finalDx = (eDx / eDist) * 75; finalDz = (eDz / eDist) * 75; }
                radarExit.style.transform = 'translate(-50%, -50%)';
                radarExit.style.left = `calc(50% + ${finalDx}px)`;
                radarExit.style.top = `calc(50% + ${finalDz}px)`;
                radarExit.style.display = 'block';
            }

            if (dist < 15) {
                this.heartbeatTimer -= delta;
                if (this.heartbeatTimer <= 0) {
                    this.heartbeatTimer = Math.max(0.3, dist * 0.08);
                    try {
                        const ctx = Synth.ctx; if(!ctx) return;
                        const osc = ctx.createOscillator();
                        const env = ctx.createGain();
                        osc.type = 'sine'; osc.frequency.setValueAtTime(45, ctx.currentTime);
                        osc.frequency.exponentialRampToValueAtTime(25, ctx.currentTime + 0.2);
                        env.gain.setValueAtTime(0, ctx.currentTime);
                        env.gain.linearRampToValueAtTime(10.0, ctx.currentTime + 0.05);
                        env.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
                        osc.connect(env); env.connect(ctx.destination);
                        osc.start(ctx.currentTime); osc.stop(ctx.currentTime + 0.4);
                    } catch(e) {}
                }
            }

            const targetRotation = Math.atan2(px - mx, pz - mz);
            let diff = targetRotation - this.monster.rotation.y;
            while (diff < -Math.PI) diff += Math.PI * 2;
            while (diff > Math.PI) diff -= Math.PI * 2;
            this.monster.rotation.y += diff * 2.0 * delta;
            
            // 2. Damage completely independent of visibility
            if (dist <= 1.2) {
                this.isDead = true;
                this.deathTimer = 2.0;
                
                try {
    const ctx = Synth.ctx;
    if(ctx) {
        const osc = ctx.createOscillator();
        const env = ctx.createGain();
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(150, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(10, ctx.currentTime + 1.0);
        env.gain.setValueAtTime(0, ctx.currentTime);
        env.gain.linearRampToValueAtTime(15.0 * (window.Settings ? window.Settings.sfxVol : 1.0), ctx.currentTime + 0.1);
        env.gain.linearRampToValueAtTime(0, ctx.currentTime + 1.0);
        osc.connect(env); env.connect(ctx.destination);
        osc.start(); osc.stop(ctx.currentTime + 1.0);
    }
} catch(e) {}
                
                const flash = document.getElementById('glitch-flash');
                if (flash) {
                    flash.style.backgroundColor = "red";
                    flash.style.display = 'block';
                    flash.style.opacity = 0;
                    flash.style.transition = 'opacity 2.0s ease-in-out';
                    
                    // Force a reflow to ensure the transition applies
                    void flash.offsetWidth;
                    
                    flash.style.opacity = 0.8;
                    flash.classList.remove('hidden');
                }
                
                this.prevTime = time;
                return false;
            }
            
            if (this.teleportCooldown === undefined) this.teleportCooldown = 2.0;
            this.teleportCooldown -= delta;
            
            if (this.teleportCooldown <= 0) {
                let canSee = false;
                const frustum = this.frustum;
                const projScreenMatrix = this.projScreenMatrix;
                this.camera.updateMatrixWorld();
                projScreenMatrix.multiplyMatrices(this.camera.projectionMatrix, this.camera.matrixWorldInverse);
                frustum.setFromProjectionMatrix(projScreenMatrix);
                
                const monsterPos = this.monster.position.clone();
                monsterPos.y = 1.0; 
                
                if (frustum.intersectsSphere(new THREE.Sphere(monsterPos, 1.5))) {
                    const toMonster = new THREE.Vector3().subVectors(monsterPos, this.camera.position);
                    toMonster.normalize();
                    
                    const raycaster = new THREE.Raycaster(this.camera.position, toMonster);
                    const intersects = raycaster.intersectObjects([...this.walls, this.monster], true);
                    for (let hit of intersects) {
                        if (hit.object.geometry && hit.object.geometry.type === 'BoxGeometry' && hit.object.material === this.wallMat) {
                            break;
                        }
                        
                        let curr = hit.object;
                        let hitMonster = false;
                        while(curr) {
                            if (curr === this.monster || curr === this.monsterMesh) { hitMonster = true; break; }
                            curr = curr.parent;
                        }
                        if (hitMonster) {
                            canSee = true;
                            break;
                        }
                    }
                }
                
                if (!canSee) {
                    const nextCell = this.getNextStep(mx, mz, px, pz);
                    if (nextCell) {
                        this.monster.position.x = nextCell.x + 0.5;
                        this.monster.position.z = nextCell.z + 0.5;
                    }
                    
                    if (this.flashlightCooldown > 0) {
                        this.teleportCooldown = 4.0; 
                    } else {
                        this.teleportCooldown = 1.0;
                    }
                } else {
                    this.teleportCooldown = 0.1;
                }
            }
        }
        
        this.prevTime = time;
        return false;
    }
    render() {
        if (!this.hasWon) {
            this.renderer.render(this.scene, this.camera);
        }
    }

    destroy() {
        document.removeEventListener('keydown', this.kd);
        document.removeEventListener('keyup', this.ku);
        Input.off('mouseLook', this.mouseLookHandler);
        this.renderer.render(this.scene, this.camera);
        this.ctx.drawImage(this.webglCanvas, 0, 0, this.canvas.width, this.canvas.height);
        this.renderer.dispose();
        
        // Remove WebGL canvas, show 2D canvas again
        this.webglCanvas.remove();
        this.canvas.style.display = 'block';
        
        const combo = document.getElementById('combo-container');
        if(combo) combo.style.display = 'block';
        
        const flash = document.getElementById('glitch-flash');
        if (flash) flash.style.opacity = 0;
    }
}
// ----------------------------------------------------
// GameEngine
// The master state controller. Connects the 2D UI, the 2D Firefly game, and the 3D Horror mode.
// Handles state transitions (Menu -> Playing -> Horror) seamlessly.
// ----------------------------------------------------
        class GameEngine {
            constructor() {
                window.currentGameEngine = this;
                
                this.canvas = document.getElementById('game-canvas');
                this.ctx = this.canvas.getContext('2d');
                this.currentState = 'MENU';
                
                this.score = 0;
                this.combo = 1;
                this.comboTimer = 0;
                this.comboCounter = 0;
                this.difficulty = 1.0;
                this.nextRedFlyScore = 1000;
                
                this.fireflies = [];
                this.particles = [];
                this.texts = [];
                this.backrooms = null;
                this.lastTime = 0;
                
                this.bindUI();
                this.resize();
                
                window.addEventListener('resize', () => this.resize());
                
                Input.on('pauseToggle', () => {
                    if (this.currentState === 'PLAYING' || this.currentState === 'PLAYING_HORROR') {
                        if (true) { // Always emit so it doesn't fail on lock bugs
                            document.exitPointerLock();
                        }
                        this.changeState('PAUSED');
                    } else if (this.currentState === 'PAUSED') {
                        if (this.backrooms) {
                            this.changeState('PLAYING_HORROR'); document.getElementById('horror-hud').style.display = 'block';
                            
                            document.body.requestPointerLock();
                        } else {
                            this.changeState('PLAYING'); document.getElementById('horror-hud').style.display = 'none';
                        }
                    }
                });
            }

            resize() {
                this.width = this.canvas.width = window.innerWidth;
                this.height = this.canvas.height = window.innerHeight;
            }

            bindUI() {
                this.screens = {
                    menu: document.getElementById('screen-menu'),
                    settings: document.getElementById('screen-settings'),
                    pause: document.getElementById('screen-pause'),
                    gameover: document.getElementById('screen-gameover'),
                    hud: document.getElementById('hud')
                };
                
                this.ui = {
                    score: document.getElementById('score-value'),
                    combo: document.getElementById('combo-value'),
                    comboFill: document.getElementById('combo-bar-fill'),
                    instruction: document.getElementById('instruction-hud')
                };
                
                document.getElementById('btn-start').addEventListener('click', () => {
                    if (document.documentElement.requestFullscreen) {
                        document.documentElement.requestFullscreen().catch(e => {});
                    }
                    this.startGame();
                });
                
                document.getElementById('btn-pause-settings').addEventListener('click', () => {
                      this.screens.pause.classList.add('hidden');
                      document.getElementById('screen-settings').classList.remove('hidden');
                  });
                  document.getElementById('btn-settings-open').addEventListener('click', () => {
                    this.screens.menu.classList.add('hidden');
                    document.getElementById('screen-settings').classList.remove('hidden');
                });
                
                document.getElementById('btn-settings-close').addEventListener('click', () => {
                    
                      document.getElementById('screen-settings').classList.add('hidden');
                      if (this.currentState === 'PAUSED') {
                          this.screens.pause.classList.remove('hidden');
                      } else {
                          this.screens.menu.classList.remove('hidden');
                      }

                });
                
                document.getElementById('btn-pause').addEventListener('click', () => {
                    if (document.pointerLockElement) {
                        document.exitPointerLock();
                    }
                    this.changeState('PAUSED');
                });
                
                document.getElementById('btn-resume').addEventListener('click', () => {
                    if (this.backrooms) {
                        this.changeState('PLAYING_HORROR');
                        
                        document.body.requestPointerLock();
                    } else {
                        this.changeState('PLAYING');
                    }
                });
                
                document.getElementById('btn-gameover-restart').addEventListener('click', () => {
                    this.changeState('MENU');
                });
                
                document.getElementById('btn-quit').addEventListener('click', () => {
                    if (document.exitFullscreen) {
                        document.exitFullscreen().catch(e => {});
                    }
                    this.backrooms = null;
                    Synth.stopHorrorAudio();
                    customMusicPlayer.play().catch(e => {});
                    this.changeState('MENU');
                });
            }

            changeState(newState) {
                this.currentState = newState;
                  const hh = document.getElementById('horror-hud');
                  if (hh) hh.style.display = (newState === 'PLAYING_HORROR') ? 'block' : 'none';
                Object.values(this.screens).forEach(s => s.classList.add('hidden'));
                
                if (newState === 'MENU') {
                    this.screens.menu.classList.remove('hidden');
                    this.initEntities();
                } else if (newState === 'PLAYING') {
                    this.screens.hud.classList.remove('hidden');
                    this.ui.instruction.innerText = "Press and hold to track fireflies";
                    this.ui.instruction.id = "instruction-hud";
                } else if (newState === 'PLAYING_HORROR') {
                    this.screens.hud.classList.remove('hidden');
                    this.ui.instruction.innerText = "Use WASD to move. Mouse to look. Find the green light.";
                    this.ui.instruction.id = "horror-hud-text";
                } else if (newState === 'PAUSED') {
                    this.screens.pause.classList.remove('hidden');
                } else if (newState === 'GAMEOVER') {
                    this.screens.gameover.classList.remove('hidden');
                }
            }

            startGame() {
                this.score = 0;
                this.combo = 1;
                this.comboTimer = 0;
                this.comboCounter = 0;
                this.difficulty = 1.0;
                this.nextRedFlyScore = 1000;
                this.backrooms = null;
                
                this.initEntities();
                this.updateHUD();
                this.changeState('PLAYING');
            }

            initEntities() {
                this.fireflies = [];
                this.particles = [];
                this.texts = [];
                
                let count = 35;
                if (Settings.swarm === 'FEW') {
                    count = 15;
                }
                if (Settings.swarm === 'SWARM') {
                    count = 60;
                }
                
                for (let i = 0; i < count; i++) {
                    this.fireflies.push(new Firefly(this, true));
                }
            }

            onFireflyCaptured(f) {
                if (f.isRed) {
                    this.triggerBackrooms();
                    return;
                }
                
                const pts = f.points * this.combo;
                this.score += pts;
                
                this.comboTimer = Math.min(100, this.comboTimer + 35);
                this.comboCounter++;
                
                if (this.comboCounter >= 4) {
                    this.combo++;
                    this.comboCounter = 0;
                    
                    this.ui.combo.classList.add('shake');
                    setTimeout(() => this.ui.combo.classList.remove('shake'), 300);
                    
                    this.comboTimer = 50;
                    Synth.playComboUp();
                    this.difficulty = Math.min(2.5, this.difficulty + 0.05);
                    
                    let maxSwarm = Settings.swarm === 'SWARM' ? 100 : (Settings.swarm === 'FEW' ? 30 : 60);
                    if (this.fireflies.length < maxSwarm) {
                        this.fireflies.push(new Firefly(this, false));
                    }
                }
                
                if (this.score >= this.nextRedFlyScore) {
                    this.nextRedFlyScore += Math.floor(1000 + Math.random() * 1500);
                    this.fireflies.push(new Firefly(this, false, true));
                }
                
                Synth.playCapture(this.combo);
                
                const numParticles = Math.min(40, 15 + (this.combo * 3));
                for (let p = 0; p < numParticles; p++) {
                    this.particles.push(new Particle(f.pos.x, f.pos.y, f.r, f.g, f.b, this.combo));
                }
                
                const scale = f.type === 'gold' ? 1.5 : 1.0;
                this.texts.push(new FloatingText(f.pos.x, f.pos.y - 20, `+${pts}`, `${f.r},${f.g},${f.b}`, scale));
                
                this.ui.score.style.transform = 'scale(1.15)';
                setTimeout(() => this.ui.score.style.transform = 'scale(1)', 100);
            }

            triggerBackrooms() {
                if (document.documentElement.requestFullscreen) {
                    document.documentElement.requestFullscreen().catch(e => {});
                }
                
                
                document.body.requestPointerLock();
                
                customMusicPlayer.pause();
                Synth.startHorrorAudio();
                
                const flash = document.getElementById('glitch-flash');
                flash.style.display = 'block'; flash.style.opacity = 1;
                
                try { this.backrooms = new BackroomsEngine(this.width, this.height, this); } catch(e) { alert('ERROR: ' + e.message + '\\n' + e.stack); }
                this.changeState('PLAYING_HORROR');
                
                setTimeout(() => { flash.style.opacity = 0; }, 150);
                  setTimeout(() => { flash.style.display = 'none'; }, 650);
                setTimeout(() => { flash.style.display = 'block'; flash.style.opacity = 1; }, 300);
                setTimeout(() => { flash.style.opacity = 0; }, 600);
            }

            updateHUD() {
                this.ui.score.innerText = this.score.toLocaleString();
                this.ui.combo.innerText = `x${this.combo}`;
                this.ui.comboFill.style.width = `${this.comboTimer}%`;
                
                if (this.combo >= 15) {
                    this.ui.comboFill.style.background = 'var(--glow-accent)';
                    this.ui.combo.style.color = 'var(--glow-accent)';
                } else if (this.combo >= 8) {
                    this.ui.comboFill.style.background = 'var(--glow-secondary)';
                    this.ui.combo.style.color = 'var(--glow-secondary)';
                } else if (this.combo > 1) {
                    this.ui.comboFill.style.background = 'var(--gold-leaf)';
                    this.ui.combo.style.color = 'var(--gold-leaf)';
                } else {
                    this.ui.comboFill.style.background = 'rgba(255,255,255,0.3)';
                    this.ui.combo.style.color = 'var(--ui-muted)';
                }
            }

            tick(currentTime) {
                if (!this.lastTime) {
                    this.lastTime = currentTime;
                }
                
                const deltaTime = Math.min(currentTime - this.lastTime, 100);
                this.lastTime = currentTime;
                
                if (this.currentState === 'PLAYING') {
                    this.ctx.fillStyle = 'rgba(5, 5, 8, 0.4)';
                    this.ctx.fillRect(0, 0, this.width, this.height);
                    
                    if (this.comboTimer > 0) {
                        const drainSpeed = 0.08 + (this.combo * 0.01);
                        this.comboTimer -= drainSpeed * (deltaTime / 16);
                        
                        if (this.comboTimer <= 0) {
                            this.comboTimer = 0;
                            this.combo = 1;
                            this.comboCounter = 0;
                            this.difficulty = Math.max(1.0, this.difficulty - 0.1);
                        }
                    }
                    
                    this.updateHUD();
                    
                    this.fireflies.forEach(f => f.update(currentTime, deltaTime));
                    
                    this.particles = this.particles.filter(p => p.life > 0);
                    this.particles.forEach(p => p.update());
                    
                    this.texts = this.texts.filter(t => t.life > 0);
                    this.texts.forEach(t => t.update());
                    
                    this.fireflies.forEach(f => f.draw(this.ctx));
                    this.particles.forEach(p => p.draw(this.ctx));
                    this.texts.forEach(t => t.draw(this.ctx));
                    
                } else if (this.currentState === 'PLAYING_HORROR') {
                    if (customMusicPlayer && !customMusicPlayer.paused) {
                        customMusicPlayer.pause();
                    }
                    if (this.backrooms) {
                        const result = this.backrooms.update(deltaTime);
                          this.backrooms.render(this.ctx);
                          
                          if (result === true || result === 'WIN') {
                              if (document.exitPointerLock) document.exitPointerLock();
                              Synth.stopHorrorAudio();
                              if (Settings.musicVol > 0 && !customMusicPlayer.muted) customMusicPlayer.play().catch(e => {});
                              
                              const flash = document.getElementById('glitch-flash');
                              if (flash) {
                                  flash.style.backgroundColor = "white";
                                  flash.style.display = 'block'; flash.style.opacity = 1;
                                  setTimeout(() => {
                                      flash.style.opacity = 0;
                                      if(this.backrooms && this.backrooms.destroy) this.backrooms.destroy();
                                      this.backrooms = null;
                                      this.changeState('PLAYING');
                                      const player = document.getElementById('custom-music-player');
                                      if (player && !window.isMuted) player.play().catch(e=>e);
                                  }, 500);
                                  setTimeout(() => { flash.style.display = 'none'; }, 800);
                              }
                          } else if (result === 'LOSE') {
                              if (document.exitPointerLock) document.exitPointerLock();
                              Synth.stopHorrorAudio();
                              
                              const flash = document.getElementById('glitch-flash');
                              if (flash) {
                                  flash.style.display = 'none';
                                  flash.style.opacity = 0;
                                  flash.classList.add('hidden');
                              }
                              
                              if(this.backrooms && this.backrooms.destroy) this.backrooms.destroy();
                              this.backrooms = null;
                              this.changeState('GAMEOVER');
                          }
                    }
                }
                
                requestAnimationFrame((time) => this.tick(time));
            }

            start() {
                this.initEntities();
                requestAnimationFrame((time) => this.tick(time));
            }
        }

        window.onload = () => {
            window.game = new GameEngine();
            window.game.start();
        };

// In-game Settings and Mute
let isMuted = false;
function toggleMute() {
    isMuted = !isMuted;
    const player = document.getElementById('custom-music-player');
    if (player) {
        player.muted = isMuted;
    }
    const btn = document.getElementById('mute-btn');
    if (btn) btn.style.background = isMuted ? 'red' : 'rgba(0,0,0,0.5)';
}

document.addEventListener('keydown', (e) => {
                      if (e.code === 'Escape' && window.game && (window.game.currentState === 'PLAYING' || window.game.currentState === 'PLAYING_HORROR')) {
                          if (document.pointerLockElement) document.exitPointerLock();
                          window.game.changeState('PAUSED');
                      }
                  });
                  
document.addEventListener('keydown', (e) => {
    if (e.code === 'KeyM') {
        toggleMute();
        const gmBtn = document.getElementById('global-mute-btn');
        if (gmBtn) gmBtn.style.background = isMuted ? 'red' : 'rgba(0,0,0,0.7)';
    }
});


// We need to wait for DOM to load
window.addEventListener('load', () => {
    const gmBtn = document.getElementById('global-mute-btn');
    if (gmBtn) {
        gmBtn.addEventListener('click', () => {
            toggleMute();
            gmBtn.style.background = isMuted ? 'red' : 'rgba(0,0,0,0.7)';
        });
    }

    const muteBtn = document.getElementById('mute-btn');
    if (muteBtn) {
        muteBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            toggleMute();
        });
    }

    const settingsBtn = document.getElementById('settings-btn');
    if (settingsBtn) {
        settingsBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            document.exitPointerLock();
            document.getElementById('screen-settings').classList.remove('hidden');
        });
    }
});
